//! Unix applets compiled into the binary (generated by scripts/ay-modules-gen.ts).
//!
//! uutils/coreutils 3e2c890eb0, findutils 83e46e7263, grep 617f541aa9, sed f8e4029a73.
//! Every utility takes its arguments as `argv`, `argv[0]` being its own name, and returns its exit status.

use std::ffi::OsString;

pub type Applet = fn(Vec<OsString>) -> i32;

